// src/main.js — точка входа прототипа «Койне» (текстовый/1D MUD-срез).
// Ответственность: интро, рендер стартовой комнаты, запуск UI.
//
// Привязка: NX-VIS-004 (видение), столпы ЭХО + ЗНАНИЕ.
// Принцип «современное-первым»: ES-модули, http (XAMPP), без сборщиков.
//
// Контракт: импортируем ТОЛЬКО публичный API textui. Сам ввод (Enter->handle)
// вешает textui.start(); здесь мы его НЕ дублируем.

import { textui } from './ui/textui.js';

// Интро — задаёт тон мира и подсказывает базовые глаголы.
// Текст игры на русском; класс 'sys' для служебного стиля терминала.
textui.print('NEXUS · срез «Койне» — субстрат записей живёт между сессиями.', 'sys');
textui.print('Столпы: ЭХО (следы прошедших странников) и ЗНАНИЕ (факты дешифруют руны).', 'sys');
textui.print('Команды: осмотреться · идти <напр> · читать <руна> · оставить <текст> · вести · знания · помощь', 'sys');
textui.print('—', 'sys');

// Рендер стартовой комнаты через публичный глагол «осмотреться» (look).
// Это держит логику отрисовки в одном месте (textui) и не дублирует её здесь.
textui.handle('осмотреться');

// Запуск интерактивного цикла: textui сам находит #log / #input,
// вешает Enter->handle и подписывается на bus 'record:written'.
textui.start();
